def set_data_path(data_dir: str, hardware: bool = False, training: bool = True, graph_type: str = "default") -> str:    
    """Build data directory paths for QAOA runs.

    Parameters
    ----------
    data_dir : str
        Base directory containing the `hardware/` and/or `training/` subfolders.
    hardware : bool, default=False
        If True, build the hardware path.
    training : bool, default=True
        If True, build the training path.
    graph_type : str, default="default"
        Graph family identifier (e.g., "erdos_renyi", "heavy_hex").

    Returns
    -------
    str or tuple of (str, str)
        If `hardware and training` is True, returns `(hardware_path, training_path)`.
        Otherwise returns the requested single path.
    """
    if hardware:
        if graph_type == "erdos_renyi":
            final_path_hardware = f"{data_dir}/hardware/{graph_type}"
        elif graph_type == "heavy_hex":
            final_path_hardware = f"{data_dir}/hardware/{graph_type}"
        elif graph_type == "line_to_full":
            final_path_hardware = f"{data_dir}/hardware/{graph_type}"
        elif graph_type == "random_regular":
            final_path_hardware = f"{data_dir}/hardware/{graph_type}" 
        else:
            final_path_hardware = ""

    if training:
        if graph_type == "erdos_renyi":
            final_path_training = f"{data_dir}/training/{graph_type}"
        elif graph_type == "heavy_hex":
            final_path_training = f"{data_dir}/training/{graph_type}"
        elif graph_type == "line_to_full":
            final_path_training = f"{data_dir}/training/{graph_type}"
        elif graph_type == "random_regular":
            final_path_training = f"{data_dir}/training/{graph_type}" 
        else:
            final_path_training = ""

    if hardware and training:
        return final_path_hardware, final_path_training
    if training:
        return final_path_training
    else:
        return final_path_hardware

def load_problem_instance(problem_path: str, graph_type: str, num_nodes: str, instance: str,
                          degree: str = None, ER_probability: str = None, swap_layers: str = None) -> list[Path]:
    """Return the paths to problem instance JSON files for a given graph family.

    Parameters
    ----------
    problem_path : str
        Base directory containing per-graph-type subfolders.
    graph_type : str
        Graph family identifier.
    num_nodes : str
        Number of nodes encoded in the filename.
    instance : str
        Instance index (zero-padded to 3 digits).
    degree : str, optional
        Degree used for ``graph_type="random_regular"``. When provided, only
        files matching ``random{degree}regular`` are returned, preventing
        accidental loading of wrong-degree instances.
    ER_probability : str, optional
        Erdos-Renyi probability suffix used for ``graph_type="erdos_renyi"``.
    swap_layers : str, optional
        Swap-layer count used for ``graph_type="line_to_full"``.

    Returns
    -------
    list[Path]
        Paths to the matching instance JSON files.
    """
    instance = str(instance).zfill(3)
    base = Path(problem_path) / graph_type

    if graph_type == "erdos_renyi":
        prob_suffix = f"erdosrenyi{ER_probability}percent" if ER_probability else ""
        problem_instance_path = f"{instance}*{num_nodes}nodes*{prob_suffix}*.json"
    elif graph_type == "heavy_hex":
        problem_instance_path = f"{instance}*{num_nodes}nodes*.json"
    elif graph_type == "line_to_full":
        swap_suffix = f"{swap_layers}swap_layers" if swap_layers else ""
        problem_instance_path = f"{instance}*{num_nodes}nodes*{swap_suffix}*.json"
    elif graph_type == "random_regular":
        degree_suffix = f"random{degree}regular" if degree else ""
        problem_instance_path = f"{instance}*{num_nodes}nodes*{degree_suffix}*.json"
    else:
        return []

    final_problem_instance_path = list(Path(base).glob(problem_instance_path))

    return final_problem_instance_path


def expected_energy_from_counts(
    counts: dict[str, int] | None,
    objective_from_bitstring: Callable[[str, Any], float],
    objective_context: Any = None,
    energy_mode: str = "full",
    top_pc: float | None = None,
) -> float | None:
    """Aggregate a measured bitstring distribution into an expected energy.

    Parameters
    ----------
    counts : dict or None
        Mapping from measured bitstrings to shot counts.
    objective_from_bitstring : callable
        Function returning the objective value for one measured bitstring.
    objective_context : Any, optional
        Extra context passed through to ``objective_from_bitstring``.
    energy_mode : {"full", "top"}, default="full"
        Aggregation mode. ``"full"`` averages over all shots, while
        ``"top"`` averages over the retained top-percent shot mass after
        sorting by descending objective value.
    top_pc : float, optional
        Retained percent used when ``energy_mode="top"``.

    Returns
    -------
    float or None
        Expected energy from the measured distribution, or ``None`` when the
        distribution is empty.
    """
    if not isinstance(counts, dict) or len(counts) == 0:
        return None

    weighted_objectives: list[tuple[float, float]] = []
    total_weight = 0.0

    for bitstring, raw_weight in counts.items():
        if raw_weight is None:
            continue

        weight = float(raw_weight)
        if weight <= 0:
            continue

        objective_value = float(objective_from_bitstring(bitstring, objective_context))
        weighted_objectives.append((objective_value, weight))
        total_weight += weight

    if total_weight == 0 or len(weighted_objectives) == 0:
        return None

    if energy_mode == "full":
        total_objective = sum(objective_value * weight for objective_value, weight in weighted_objectives)
        return total_objective / total_weight

    if energy_mode != "top":
        raise ValueError(f"Unknown energy_mode: {energy_mode}")

    if top_pc is None:
        raise ValueError("top_pc must be provided when energy_mode='top'")
    if not 0 < float(top_pc) <= 100:
        raise ValueError("top_pc must lie in (0, 100]")

    target_weight = total_weight * float(top_pc) / 100.0
    kept_weight = 0.0
    kept_objective = 0.0

    for objective_value, weight in sorted(weighted_objectives, key=lambda item: item[0], reverse=True):
        take_weight = min(weight, target_weight - kept_weight)
        if take_weight <= 0:
            continue

        kept_objective += objective_value * take_weight
        kept_weight += take_weight

        if kept_weight >= target_weight:
            break

    if kept_weight == 0:
        return None

    return kept_objective / kept_weight

class QAOAHardware:

    """Container for a single QAOA hardware run parsed from IBM JSON output.

    Attributes
    ----------
    instance_name : str
        Short instance identifier.
    QPU_time : float or int or None
        Job-level total QPU time (from the JSON `total_time` field).
    num_shots : int or None
        Number of shots used for the hardware run.
    problem_class : str
        Problem class label (e.g., MaxCut).
    training_method : str
        Training method used to generate parameters.
    expected_energy : float
        Energy implied by the measured hardware distribution.
    file_file : str or None
        Optional reference to a result file.
    """

    def __init__(self, short_name, total_time, num_shots,
             problem_class, method, expected_energy, result_file,
             job_p, training_p, counts, params=None, trainer=None):
        self.instance_name = short_name
        self.QPU_time = total_time
        self.num_shots = num_shots
        self.problem_class = problem_class
        self.training_method = method
        self.expected_energy = expected_energy
        self.file_name = result_file
        self.job_p = job_p              # from hardware job filename
        self.training_p = training_p    # from circuit_metadata.method (or result_file)
        self.counts = counts
        self.params = params
        self.trainer = trainer


    # Method to return problem instance file paths for hardware
    @classmethod
    def locate_hardware_instance(cls, final_path_hardware: str, graph_type: str, instance: str, num_nodes: str, p: str,
        ER_probability: str = None, swap_layers: str = None, degree: str = None) -> list[Path]:
        """Locate hardware JSON files matching an instance specification.

        Parameters
        ----------
        final_path_hardware : str
            Directory containing hardware JSON files.
        graph_type : str
            Graph family identifier.
        instance : str
            Instance index/identifier (as used in the filename pattern).
        num_nodes : str
            Number of nodes encoded in the filename.
        p : str
            QAOA depth parameter encoded in the filename.
        ER_probability : str, optional
            Erdos-Renyi probability suffix used for `graph_type="erdos_renyi"`.
        swap_layers : str, optional
            Swap-layer count used for `graph_type="line_to_full"`.
        degree : str, optional
            Degree used for `graph_type="random_regular"`.

        Returns
        -------
        list of pathlib.Path
            Matching JSON file paths (possibly empty).
        """
        
        if graph_type == "heavy_hex":
            instance_path = f"00{instance}N{num_nodes}HH*_{p}_*.json"
        elif graph_type == "erdos_renyi":
            instance_path = f"00{instance}N{num_nodes}ER{ER_probability}_{p}_*.json"
        elif graph_type == "line_to_full":
            instance_path = f"00{instance}N{num_nodes}L2S{swap_layers}_{p}_*.json"
        elif graph_type == "random_regular":
            instance_path = f"00{instance}N{num_nodes}R{degree}R_{p}_*.json"
        else:
            return []

        instance_paths_final_hardware = list(Path(final_path_hardware).glob(instance_path))
        
        return instance_paths_final_hardware

    # Method to load problem instance file paths for hardware and return class instances
    @classmethod
    def load_hardware_instance(
        cls,
        instance_path: Path,
        objective_from_bitstring: Callable[[str, Any], float],
        objective_context: Any = None,
        energy_mode: str = "full",
        top_pc: float | None = None,
    ) -> list["QAOAHardware"]:
        """Parse a hardware JSON file into `QAOAHardware` records.

        Parameters
        ----------
        instance_path : pathlib.Path
            Path to a hardware JSON file (job-level record plus circuit-level records).
        objective_from_bitstring : callable
            Function used to evaluate one measured bitstring.
        objective_context : Any, optional
            Extra context passed through to ``objective_from_bitstring``.
        energy_mode : {"full", "top"}, default="full"
            Aggregation mode used to turn the measured distribution into an
            expected energy.
        top_pc : float, optional
            Retained percent used when ``energy_mode="top"``.

        Returns
        -------
        list of QAOAHardware
            One object per circuit-level record containing hardware energy
            derived from measured counts.

        Notes
        -----
        Performs file I/O and skips incomplete records.
        """

        all_data: list["QAOAHardware"] = []

        with instance_path.open("r") as f:
            content = json.load(f)

        # Convert to list if not already
        if not isinstance(content, list):
            content = [content]

        # Job-level fields are always on top
        QPU_time = content[0].get("total_time")
        num_shots = content[0].get("num_shots")

        # job_p from the hardware job filename ---
        m = re.search(r"_(\d+)_", instance_path.name)
        job_p = int(m.group(1)) if m else None

        for data in content:
            
            # Check that this is a circuit-level record 
            metadata = data.get("metadata")
            if not metadata:
                continue

            circuit_md = metadata.get("circuit_metadata")
            if not circuit_md:
                continue

            # Require eval_energy (defines a valid QAOA run) 
            if "eval_energy" not in circuit_md:
                continue

            # Required circuit-level fields 
            instance_name = circuit_md.get("short_name")
            problem_class = circuit_md.get("problem_class")
            training_method = circuit_md.get("method")
            eval_energy = circuit_md.get("eval_energy")
            file_name = circuit_md.get("result_file")
            params = circuit_md.get("params")
            trainer = circuit_md.get("trainer")
            counts = data.get("counts")

            if not isinstance(counts, dict) or len(counts) == 0:
                continue

            expected_energy = expected_energy_from_counts(
                counts,
                objective_from_bitstring,
                objective_context=objective_context,
                energy_mode=energy_mode,
                top_pc=top_pc,
            )

            training_p = None

            if isinstance(training_method, str):
                m2 = re.search(r"(\d+)$", training_method)   # grabs trailing number
                if m2:
                    training_p = int(m2.group(1))

            # fallback: parse from result_file if method didn't end with a number
            if training_p is None and isinstance(file_name, str):
                m3 = re.search(r"_(\d+)\.json$", file_name)
                if m3:
                    training_p = int(m3.group(1))

            # If any essential circuit info is missing, skip
            if any(v is None for v in (
                instance_name,
                problem_class,
                training_method,
                expected_energy,
                eval_energy,
            )):
                continue

            run = cls(
                instance_name,
                QPU_time,
                num_shots,
                problem_class,
                training_method,
                expected_energy,
                file_name,
                job_p,
                training_p,
                counts,
                params=params,
                trainer=trainer,
            )

            all_data.append(run)

        # total_time in hardware JSON is job-level; split evenly across valid methods.
        if QPU_time is not None and len(all_data) > 0:
            qpu_time_per_method = QPU_time / len(all_data)
            for run in all_data:
                run.QPU_time = qpu_time_per_method

        return all_data

class QAOATraining:

    """Container for QAOA training metadata parsed from training JSON output.

    Attributes
    ----------
    file_name : str
        Instance identifier (typically from `args.save_file`).
    pre_processing_time : float or int or None
        Duration reported for preprocessing.
    pre_processor_name : str or None
        Preprocessor name reported in the JSON.
    train_duration_per_iter : list
        Training durations per outer iteration.
    expected_energy_per_iter : list
        Energies per outer iteration.
    trainer_name_per_iter : list
        Trainer dictionaries per outer iteration.
    train_duration_per_layer : list of list
        Training durations per layer-step nested within each outer iteration.
    expected_energy_per_layer : list of list
        Energies per layer-step nested within each outer iteration.
    trainer_name_per_layer : list of list
        Trainer dictionaries per layer-step nested within each outer iteration.
    num_depth_iter : list of list
        Depth-step keys (as strings) per outer iteration.
    """

    def __init__(
        self,
        save_file,
        physical_file_name,
        duration,
        pre_processor_name,
        train_duration_iter,
        energy_iter,
        trainer_name_iter,
        train_duration_layer,
        energy_layer,
        trainer_name_layer,
        num_depth_iter,
        stage_summaries,
    ):
        self.file_name = save_file
        self.physical_file_name = physical_file_name
        self.pre_processing_time = duration
        self.pre_processor_name = pre_processor_name

        self.train_duration_per_iter = train_duration_iter
        self.expected_energy_per_iter = energy_iter
        self.trainer_name_per_iter = trainer_name_iter

        self.train_duration_per_layer = train_duration_layer
        self.expected_energy_per_layer = energy_layer
        self.trainer_name_per_layer = trainer_name_layer

        self.num_depth_iter = num_depth_iter
        self.stage_summaries = stage_summaries

    @classmethod
    def locate_training_instance(cls, final_path_training: str, graph_type: str, instance: str, num_nodes: str, p: str,
                                 ER_probability: str = None, swap_layers: str = None, degree: str = None) -> list[Path]:

        """Locate training JSON files matching an instance specification.

        Parameters
        ----------
        final_path_training : str
            Directory containing training JSON files.
        graph_type : str
            Graph family identifier.
        instance : str
            Instance index/identifier; will be zero-padded to 3 digits.
        num_nodes : str
            Number of nodes encoded in the filename.
        p : str
            QAOA depth parameter encoded in the filename.
        ER_probability : str, optional
            Erdos-Renyi probability suffix used for `graph_type="erdos_renyi"`.
        swap_layers : str, optional
            Swap-layer count used for `graph_type="line_to_full"`.
        degree : str, optional
            Degree used for `graph_type="random_regular"`.

        Returns
        -------
        list of pathlib.Path
            Matching JSON file paths (possibly empty).
        """

        instance = str(instance).zfill(3)

        if graph_type == "heavy_hex":
            instance_path = f"*{instance}N{num_nodes}HH*_MC_*{p}"

        elif graph_type == "erdos_renyi":
            instance_path = f"*{instance}N{num_nodes}ER{ER_probability}_MC_*{p}"

        elif graph_type == "line_to_full":
            instance_path = f"*{instance}N{num_nodes}L2S{swap_layers}_MC_*{p}"

        elif graph_type == "random_regular":
            instance_path = f"*{instance}N{num_nodes}R{degree}R*_MC_*{p}"

        else:
            return []

        training_dir = Path(final_path_training)
        exact_matches = list(training_dir.glob(f"{instance_path}.json"))
        duplicate_matches = list(training_dir.glob(f"{instance_path} (*.json"))
        return exact_matches + duplicate_matches

    @classmethod
    def load_training_instance(cls, instance_path: Path) -> "QAOATraining":

        """Parse a training JSON file into a `QAOATraining` object.

        Parameters
        ----------
        instance_path : pathlib.Path
            Path to a training JSON file.

        Returns
        -------
        QAOATraining
            Parsed training metadata and per-iteration/per-layer sequences.

        Notes
        -----
        Performs file I/O and skips iterations/layers missing required keys.
        """

        with instance_path.open("r") as f:
            data = json.load(f)

        # Load pre_proceesing data
        args = data.get("args")

        file_name = instance_path.name
        if args is not None and "save_file" in args:
            file_name = args["save_file"]
    
        pre_processing = data.get("pre_processing")
        if pre_processing is None:
            pre_processing = {}

        pre_processor_name = pre_processing.get("pre_processor_name")
        pre_processing_time = pre_processing.get("duration")

        # Load main data
        num_iterations = []
        for key in data.keys():
            try:
                int(key)
                num_iterations.append(key)
            except ValueError:
                pass
        num_iterations = sorted(num_iterations, key=int)

        train_duration_per_iter = []
        expected_energy_per_iter = []
        trainer_name_per_iter = []

        train_duration_per_layer = []
        expected_energy_per_layer = []
        trainer_name_per_layer = []

        num_depth_iter = []
        stage_summaries = []

        for element in num_iterations:
            classical_iteration = data.get(element)
            if classical_iteration is None:
                continue

            if "train_duration" not in classical_iteration or "energy" not in classical_iteration:
                continue
            if "trainer" not in classical_iteration:
                continue

            trainer_info = classical_iteration["trainer"]
            trainer_name = (
                trainer_info.get("trainer_name")
                if isinstance(trainer_info, dict)
                else None
            )
            optimized_angles = classical_iteration.get("optimized_qaoa_angles")

            train_duration_per_iter.append(classical_iteration["train_duration"])
            expected_energy_per_iter.append(classical_iteration["energy"])
            trainer_name_per_iter.append(trainer_info)
            stage_summaries.append(
                {
                    "stage": int(element),
                    "trainer_name": trainer_name,
                    "train_duration": classical_iteration["train_duration"],
                    "optimized_qaoa_angles": optimized_angles,
                }
            )

            current_iter_depth_keys = []
            current_iter_durations = []
            current_iter_energies = []
            current_iter_trainers = []

            for key2 in classical_iteration.keys():
                try:
                    int(key2)
                    current_iter_depth_keys.append(key2)
                except ValueError:
                    pass
            current_iter_depth_keys = sorted(current_iter_depth_keys, key=int)

            for element2 in current_iter_depth_keys:
                layer_iteration = classical_iteration.get(element2)
                if layer_iteration is None:
                    continue

                if "train_duration" not in layer_iteration or "energy" not in layer_iteration:
                    continue
                if "trainer" not in layer_iteration:
                    continue

                current_iter_durations.append(layer_iteration["train_duration"])
                current_iter_energies.append(layer_iteration["energy"])
                current_iter_trainers.append(layer_iteration["trainer"])

            num_depth_iter.append(current_iter_depth_keys)
            train_duration_per_layer.append(current_iter_durations)
            expected_energy_per_layer.append(current_iter_energies)
            trainer_name_per_layer.append(current_iter_trainers)

        return cls(
            file_name,
            instance_path.name,
            pre_processing_time,
            pre_processor_name,
            train_duration_per_iter,
            expected_energy_per_iter,
            trainer_name_per_iter,
            train_duration_per_layer,
            expected_energy_per_layer,
            trainer_name_per_layer,
            num_depth_iter,
            stage_summaries,
        )


def _normalize_angle_list(values: Any) -> list[float] | None:
    """Convert a serialized angle list to floats when possible."""
    if not isinstance(values, list):
        return None
    try:
        return [float(value) for value in values]
    except (TypeError, ValueError):
        return None


def _max_abs_angle_diff(left: list[float] | None, right: list[float] | None) -> float:
    """Return the largest elementwise absolute difference between two lists."""
    if not left or not right:
        return np.nan
    return max(abs(a - b) for a, b in zip(left, right))


def _as_finite_float(value: Any) -> float:
    """Return a finite float or NaN for loose notebook metadata values."""
    try:
        numeric = float(value)
    except (TypeError, ValueError):
        return np.nan
    return numeric if np.isfinite(numeric) else np.nan


def _choose_stage_for_method(candidates: list[pd.Series], method: str) -> tuple[pd.Series | None, list[str]]:
    """Pick a stage when multiple physical files or stages can satisfy a match."""
    notes: list[str] = []
    if not candidates:
        return None, notes
    if len(candidates) == 1:
        return candidates[0], notes

    unique_stage_trainer = {
        (
            int(candidate["stage"]),
            str(candidate["trainer_name"]),
        )
        for candidate in candidates
    }
    if len(unique_stage_trainer) == 1:
        notes.append("resolved_duplicate_physical_files")
        return sorted(
            candidates,
            key=lambda candidate: str(candidate["physical_training_file"]),
        )[0], notes

    if "no_opt" in method:
        chosen_stage = min(int(candidate["stage"]) for candidate in candidates)
        notes.append("resolved_by_method_suffix")
    elif "angleOpt" in method or "_opt_" in method or method.endswith("_opt"):
        chosen_stage = max(int(candidate["stage"]) for candidate in candidates)
        notes.append("resolved_by_method_suffix")
    else:
        return None, notes

    stage_candidates = [
        candidate for candidate in candidates if int(candidate["stage"]) == chosen_stage
    ]
    return sorted(
        stage_candidates,
        key=lambda candidate: str(candidate["physical_training_file"]),
    )[0], notes


def _build_stage_manifest(df_training: pd.DataFrame) -> pd.DataFrame:
    """Expand stage-level training metadata into a flat manifest table."""
    stage_rows: list[dict[str, Any]] = []

    for _, row in df_training.iterrows():
        file_name = row["file_name"]
        physical_file = row["physical_training_file"]
        pre_processing_time = (
            row["pre_processing_time"] if pd.notna(row["pre_processing_time"]) else 0.0
        )
        stage_summaries = row["stage_summaries"]

        if not isinstance(stage_summaries, list):
            continue

        running_outer = float(pre_processing_time)
        ordered_stages = sorted(stage_summaries, key=lambda s: int(s.get("stage", -1)))

        for stage_info in ordered_stages:
            outer_duration = stage_info.get("train_duration")
            if outer_duration is None:
                continue

            running_outer += float(outer_duration)
            stage_rows.append(
                {
                    "file_name": file_name,
                    "physical_training_file": physical_file,
                    "stage": int(stage_info.get("stage", -1)),
                    "trainer_name": stage_info.get("trainer_name"),
                    "optimized_qaoa_angles": stage_info.get("optimized_qaoa_angles"),
                    "outer_duration": float(outer_duration),
                    "outer_init_duration_sum": running_outer,
                }
            )

    return pd.DataFrame(stage_rows)


def _build_inner_duration_tables(df_flat: pd.DataFrame) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Build cumulative inner-stage duration tables from flattened training logs."""
    df_sb = df_flat.copy()
    df_sb["depth_step"] = pd.to_numeric(df_sb["depth_step"], errors="coerce")
    df_sb["iteration"] = pd.to_numeric(df_sb["iteration"], errors="coerce")
    df_sb["stage"] = pd.to_numeric(df_sb["stage"], errors="coerce")

    inner = (
        df_sb.loc[
            df_sb["level"].eq("inner") & df_sb["depth_step"].notna(),
            ["file_name", "physical_training_file", "iteration", "depth_step", "duration"],
        ]
        .groupby(
            ["file_name", "physical_training_file", "iteration", "depth_step"],
            as_index=False,
        )["duration"]
        .sum()
        .sort_values(["file_name", "physical_training_file", "iteration", "depth_step"])
    )

    if not inner.empty:
        inner["inner_cum_within_stage"] = inner.groupby(
            ["file_name", "physical_training_file", "iteration"]
        )["duration"].cumsum()
    else:
        inner["inner_cum_within_stage"] = []

    inner_totals = (
        inner.groupby(["file_name", "physical_training_file", "iteration"], as_index=False)[
            "duration"
        ]
        .sum()
        .rename(columns={"duration": "inner_stage_total"})
    )

    return inner, inner_totals


def _resolve_training_stage(
    hw_row: pd.Series,
    df_stage_manifest: pd.DataFrame,
    tol: float = 1e-8,
) -> dict[str, Any]:
    """Resolve one hardware row to the matching training stage."""
    file_name = hw_row["file_name"]
    method = str(hw_row["training_method"])
    params = _normalize_angle_list(hw_row["params"])
    candidates = df_stage_manifest[df_stage_manifest["file_name"] == file_name].copy()

    if candidates.empty:
        return {
            "matched_stage": np.nan,
            "matched_stage_trainer": np.nan,
            "physical_training_file": np.nan,
            "training_match_status": "missing_training_file",
            "training_match_note": "no matching logical training file",
            "outer_init_duration_sum": np.nan,
        }

    notes: list[str] = []
    if candidates["physical_training_file"].nunique() > 1:
        notes.append("duplicate_logical_file")

    if params is None:
        return {
            "matched_stage": np.nan,
            "matched_stage_trainer": np.nan,
            "physical_training_file": np.nan,
            "training_match_status": "no_stage_match",
            "training_match_note": "hardware params missing",
            "outer_init_duration_sum": np.nan,
        }

    matches: list[tuple[pd.Series, float]] = []
    for _, candidate in candidates.iterrows():
        angles = _normalize_angle_list(candidate["optimized_qaoa_angles"])
        if angles is None or len(angles) != len(params):
            continue

        diff = _max_abs_angle_diff(params, angles)
        if diff <= tol:
            matches.append((candidate, diff))

    if not matches:
        job_p = _as_finite_float(hw_row.get("job_p"))
        training_p = _as_finite_float(hw_row.get("training_p"))
        is_depth_prefix_row = (
            np.isfinite(job_p)
            and np.isfinite(training_p)
            and training_p > job_p
        )

        if is_depth_prefix_row:
            depth_prefix_candidates: list[pd.Series] = []
            for _, candidate in candidates.iterrows():
                angles = _normalize_angle_list(candidate["optimized_qaoa_angles"])
                if angles is None or len(angles) < len(params):
                    continue
                depth_prefix_candidates.append(candidate)

            chosen, fallback_notes = _choose_stage_for_method(depth_prefix_candidates, method)
            if chosen is not None:
                return {
                    "matched_stage": int(chosen["stage"]),
                    "matched_stage_trainer": chosen["trainer_name"],
                    "physical_training_file": chosen["physical_training_file"],
                    "training_match_status": "matched",
                    "training_match_note": "; ".join(
                        notes + fallback_notes + ["depth_prefix_match_without_angle_equality"]
                    ),
                    "outer_init_duration_sum": float(chosen["outer_init_duration_sum"]),
                }

        return {
            "matched_stage": np.nan,
            "matched_stage_trainer": np.nan,
            "physical_training_file": np.nan,
            "training_match_status": "no_stage_match",
            "training_match_note": "no parameter match",
            "outer_init_duration_sum": np.nan,
        }

    matches.sort(
        key=lambda item: (
            item[1],
            int(item[0]["stage"]),
            str(item[0]["physical_training_file"]),
        )
    )

    chosen, match_notes = _choose_stage_for_method([match[0] for match in matches], method)
    notes.extend(match_notes)
    if chosen is None:
        return {
            "matched_stage": np.nan,
            "matched_stage_trainer": np.nan,
            "physical_training_file": np.nan,
            "training_match_status": "ambiguous_stage_match",
            "training_match_note": "; ".join(notes + ["multiple stage matches"]),
            "outer_init_duration_sum": np.nan,
        }

    return {
        "matched_stage": int(chosen["stage"]),
        "matched_stage_trainer": chosen["trainer_name"],
        "physical_training_file": chosen["physical_training_file"],
        "training_match_status": "matched",
        "training_match_note": "; ".join(notes),
        "outer_init_duration_sum": float(chosen["outer_init_duration_sum"]),
    }


def _resolve_inner_duration(
    hw_row: dict[str, Any],
    inner: pd.DataFrame,
    inner_totals: pd.DataFrame,
) -> float:
    """Resolve cumulative inner-loop duration for one matched hardware row."""
    if hw_row["training_match_status"] != "matched":
        return np.nan

    file_name = hw_row["file_name"]
    physical_file = hw_row["physical_training_file"]
    matched_stage = hw_row["matched_stage"]
    job_p = hw_row["job_p"]

    previous_total = inner_totals.loc[
        (inner_totals["file_name"] == file_name)
        & (inner_totals["physical_training_file"] == physical_file)
        & (inner_totals["iteration"] < matched_stage),
        "inner_stage_total",
    ].sum()

    current_stage = inner.loc[
        (inner["file_name"] == file_name)
        & (inner["physical_training_file"] == physical_file)
        & (inner["iteration"] == matched_stage)
        & (inner["depth_step"] <= job_p)
    ].sort_values("depth_step")

    current_total = (
        0.0 if current_stage.empty else float(current_stage.iloc[-1]["inner_cum_within_stage"])
    )
    return float(previous_total + current_total)


def resolve_hardware_training_costs(
    df_training: pd.DataFrame,
    df_flat: pd.DataFrame,
    df_hardware: pd.DataFrame,
    tol: float = 1e-8,
) -> pd.DataFrame:
    """Attach stage-aware training costs to hardware rows.

    This keeps the notebook-level workflow simple while preserving the
    metadata-aware matching logic between hardware rows and multi-stage
    training files.
    """
    df_stage_manifest = _build_stage_manifest(df_training)
    inner, inner_totals = _build_inner_duration_tables(df_flat)

    df_hw = df_hardware.copy()
    df_hw["job_p"] = pd.to_numeric(df_hw["job_p"], errors="coerce").astype("float64")

    resolved_rows: list[dict[str, Any]] = []
    for _, hw_row in df_hw.iterrows():
        resolved = _resolve_training_stage(hw_row, df_stage_manifest, tol=tol)
        merged = hw_row.to_dict()
        merged.update(resolved)
        merged["inner_duration_sum"] = _resolve_inner_duration(merged, inner, inner_totals)

        if merged["training_match_status"] == "matched":
            merged["total_train_cost"] = (
                merged["outer_init_duration_sum"] + merged["inner_duration_sum"]
            )
        else:
            merged["total_train_cost"] = np.nan
            if pd.isna(merged["inner_duration_sum"]):
                merged["inner_duration_sum"] = np.nan

        resolved_rows.append(merged)

    return pd.DataFrame(resolved_rows)
